package com.hbm.client.generator.stirling;
import com.hbm.client.model.LegacyItemTransforms;import com.hbm.machine.generator.stirling.*;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.world.item.*;
/** Source ItemRenderBase,GUI-1.5/3.25,commonY90 and exact wall-clock animation or broken-cog static0. */
public final class StirlingItemRenderer extends BlockEntityWithoutLevelRenderer {
 public StirlingItemRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}@Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack pose,MultiBufferSource buffers,int light,int overlay){if(!(stack.getItem() instanceof StirlingItem item))return;pose.pushPose();if(LegacyItemTransforms.isHeld(context))LegacyItemTransforms.held(pose,context);else pose.translate(.5,.5,.5);if(context==ItemDisplayContext.GUI){pose.scale(1F/16,-1F/16,1F/16);pose.translate(0,2,0);pose.mulPose(Axis.XP.rotationDegrees(-30));pose.mulPose(Axis.YP.rotationDegrees(45));pose.scale(-1,-1,-1);pose.translate(0,-1.5,0);pose.scale(3.25F,3.25F,3.25F);}else{boolean entity=context==ItemDisplayContext.GROUND||context==ItemDisplayContext.FIXED||context==ItemDisplayContext.NONE;if(entity)pose.scale(1.5F,1.5F,1.5F);else pose.translate(.5,.25,0);pose.scale(.25F,.25F,.25F);if(context!=ItemDisplayContext.THIRD_PERSON_LEFT_HAND&&context!=ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)pose.mulPose(Axis.YP.rotationDegrees(90));}pose.mulPose(Axis.YP.rotationDegrees(90));boolean cog=!StirlingItem.broken(stack);StirlingRenderer.common(cog?System.currentTimeMillis()%3600*.1F:0,cog,item.kind.gear,pose,buffers,light,overlay);pose.popPose();}
}
